/// <summary>
/// &lt;Table&gt; structure element
/// </summary>
/// <remarks>Source: SELayer.mdl; Java: org.verapdf.model.selayer.SETable.
/// </remarks>
public interface ISETable : global::VeraPdf.Model.PDLayer.IPDStructElem
{
    /// <summary>
    /// Header associations may be expressed by Headers/IDs or by TH Scope attributes.
    /// C# PORT: Validate logical spans and associations, not just visual cell geometry.
    /// false, if the table&apos;s structure is not determinable via Headers and IDs,
    /// and structure elements of type TH don&apos;t have a Scope attribute
    /// </summary>
    /// <remarks>DSL Boolean; may be absent or invalid. Java getter: getuseHeadersAndIdOrScope.</remarks>
    bool? GetuseHeadersAndIdOrScope();
    /// <summary>
    /// column span of the table
    /// </summary>
    /// <remarks>DSL Integer; may be absent or invalid. Java getter: getcolumnSpan.</remarks>
    long? GetcolumnSpan();
    /// <summary>
    /// row span of the table
    /// </summary>
    /// <remarks>DSL Integer; may be absent or invalid. Java getter: getrowSpan.</remarks>
    long? GetrowSpan();
    /// <summary>
    /// number of row with wrong column span
    /// </summary>
    /// <remarks>DSL Integer; may be absent or invalid. Java getter: getnumberOfRowWithWrongColumnSpan.</remarks>
    long? GetnumberOfRowWithWrongColumnSpan();
    /// <summary>
    /// number of column with wrong row span
    /// </summary>
    /// <remarks>DSL Integer; may be absent or invalid. Java getter: getnumberOfColumnWithWrongRowSpan.</remarks>
    long? GetnumberOfColumnWithWrongRowSpan();
    /// <summary>
    /// column span of row, which number contains property numberOfRowWithWrongColumnSpan
    /// </summary>
    /// <remarks>DSL Integer; may be absent or invalid. Java getter: getwrongColumnSpan.</remarks>
    long? GetwrongColumnSpan();
}

